def kthInGrid(grid, k):
    m, n = len(grid), len(grid[0])

    def count_le(x):
        row, col, total = m - 1, 0, 0
        while row >= 0 and col < n:
            if grid[row][col] > x:
                row -= 1
            else:
                total += row + 1
                col += 1
        return total

    lo, hi = grid[0][0], grid[m - 1][n - 1]
    while lo < hi:
        mid = (lo + hi) // 2
        if count_le(mid) >= k:
            hi = mid
        else:
            lo = mid + 1
    return lo
